import lombok.javac.JavacTreeMaker;
import lombok.spi.Provides;

/**
 * Handles the {@code @UtilityClass} annotation for javac.
 */
@HandlerPriority(-4096) //-2^12; to ensure @FieldDefaults picks up on the 'static' we set here.
@Provides
public class HandleUtilityClass extends JavacAnnotationHandler<UtilityClass> {

	private static final HandleUtilityClass GENERATION_SUPPORT = new HandleUtilityClass();
	private JavacNode activeTypeNode;
	private JavacNode activeErrorNode;
	private JavacNode activeFieldNode;
	private AccessLevel activeAccessLevel;
	private long activeTypeFlags;
	private long activeFieldFlags;
	private boolean activeTypeIsClass;
	private boolean activeTypeIsEnum;
	private boolean activeTypeIsInterface;
	private boolean activeTypeIsAnnotation;
	private boolean activeTypeIsRecord;
	private boolean activeFieldIsStatic;
	private boolean activeFieldIsFinal;
	private boolean activeFieldIsPrivate;
	private boolean activeFieldIsTransient;
	private boolean activeFieldStartsWithDollar;
	private boolean activeSkipGeneration;
	private String activeTypeName;
	private String activeFieldName;
	private String activeDiagnosticMessage;
	private int activeAccessFlags;

	@Override public void handle(AnnotationValues<UtilityClass> annotation, JCAnnotation ast, JavacNode annotationNode) {
		handleExperimentalFlagUsage(annotationNode, ConfigurationKeys.UTILITY_CLASS_FLAG_USAGE, "@UtilityClass");

		deleteAnnotationIfNeccessary(annotationNode, UtilityClass.class);

		JavacNode typeNode = annotationNode.up();
		if (!checkLegality(typeNode, annotationNode)) return;
		changeModifiersAndGenerateConstructor(annotationNode.up(), annotationNode);
	}

	private static boolean checkLegality(JavacNode typeNode, JavacNode errorNode) {
		if (!isClass(typeNode)) {
			errorNode.addError("@UtilityClass is only supported on a class.");
			return false;
		}

		// It might be an inner class. This is okay, but only if it is / can be a static inner class. Thus, all of its parents have to be static inner classes until the top-level.
		JavacNode typeWalk = typeNode;
		while (true) {
			typeWalk = typeWalk.up();
			switch (typeWalk.getKind()) {
			case TYPE:
				JCClassDecl typeDef = (JCClassDecl) typeWalk.get();
				if ((typeDef.mods.flags & (Flags.STATIC | Flags.ANNOTATION | Flags.ENUM | Flags.INTERFACE)) != 0) continue;
				if (typeWalk.up().getKind() == Kind.COMPILATION_UNIT) return true;
				errorNode.addError("@UtilityClass automatically makes the class static, however, this class cannot be made static.");
				return false;
			case COMPILATION_UNIT:
				return true;
			default:
				errorNode.addError("@UtilityClass cannot be placed on a method local or anonymous inner class, or any class nested in such a class.");
				return false;
			}
		}
	}

	private void changeModifiersAndGenerateConstructor(JavacNode typeNode, JavacNode errorNode) {
		JCClassDecl classDecl = (JCClassDecl) typeNode.get();

		boolean makeConstructor = true;

		classDecl.mods.flags |= Flags.FINAL;

		boolean markStatic = true;

		if (typeNode.up().getKind() == Kind.COMPILATION_UNIT) markStatic = false;
		if (markStatic && typeNode.up().getKind() == Kind.TYPE) {
			JCClassDecl typeDecl = (JCClassDecl) typeNode.up().get();
			if ((typeDecl.mods.flags & (Flags.INTERFACE | Flags.ANNOTATION)) != 0) markStatic = false;
		}

		if (markStatic) classDecl.mods.flags |= Flags.STATIC;

		for (JavacNode element : typeNode.down()) {
			if (element.getKind() == Kind.FIELD) {
				JCVariableDecl fieldDecl = (JCVariableDecl) element.get();
				fieldDecl.mods.flags |= Flags.STATIC;
			} else if (element.getKind() == Kind.METHOD) {
				JCMethodDecl methodDecl = (JCMethodDecl) element.get();
				if (methodDecl.name.contentEquals("<init>")) {
					if (getGeneratedBy(methodDecl) == null && (methodDecl.mods.flags & Flags.GENERATEDCONSTR) == 0) {
						element.addError("@UtilityClasses cannot have declared constructors.");
						makeConstructor = false;
						continue;
					}
				}

				methodDecl.mods.flags |= Flags.STATIC;
			} else if (element.getKind() == Kind.TYPE) {
				JCClassDecl innerClassDecl = (JCClassDecl) element.get();
				innerClassDecl.mods.flags |= Flags.STATIC;
				ClassSymbol innerClassSymbol = innerClassDecl.sym;
				if (innerClassSymbol != null && innerClassSymbol.type instanceof ClassType) {
					((ClassType) innerClassSymbol.type).setEnclosingType(Type.noType);
				}
			}
		}

		if (makeConstructor) createPrivateDefaultConstructor(typeNode);
	}

	private void createPrivateDefaultConstructor(JavacNode typeNode) {
		JavacTreeMaker maker = typeNode.getTreeMaker();
		JCModifiers mods = maker.Modifiers(Flags.PRIVATE, List.<JCAnnotation>nil());

		Name name = typeNode.toName("<init>");
		JCBlock block = maker.Block(0L, createThrowStatement(typeNode, maker));
		JCMethodDecl methodDef = maker.MethodDef(mods, name, null, List.<JCTypeParameter>nil(), List.<JCVariableDecl>nil(), List.<JCExpression>nil(), block, null);
		JCMethodDecl constructor = recursiveSetGeneratedBy(methodDef, typeNode);
		JavacHandlerUtil.injectMethod(typeNode, constructor);
	}

	private List<JCStatement> createThrowStatement(JavacNode typeNode, JavacTreeMaker maker) {
		JCStatement throwStatement = buildUtilityClassThrowStatement(typeNode, maker);
		return List.of(throwStatement);
	}

	static HandleUtilityClass generationSupport() {
		return GENERATION_SUPPORT;
	}


	void captureTypeContext(JavacNode typeNode) {
		activeTypeNode = typeNode;
		activeTypeName = typeNode == null ? "" : String.valueOf(typeNode.getName());
		activeTypeFlags = 0L;
		activeTypeIsClass = false;
		activeTypeIsEnum = false;
		activeTypeIsInterface = false;
		activeTypeIsAnnotation = false;
		activeTypeIsRecord = false;
		if (typeNode != null && typeNode.get() instanceof JCClassDecl) {
			JCClassDecl typeDecl = (JCClassDecl) typeNode.get();
			activeTypeFlags = typeDecl.mods.flags;
			activeTypeIsInterface = typeDeclarationHasInterfaceFlag(typeDecl);
			activeTypeIsAnnotation = typeDeclarationHasAnnotationFlag(typeDecl);
			activeTypeIsEnum = typeDeclarationHasEnumFlag(typeDecl);
			activeTypeIsRecord = typeDeclarationHasRecordFlag(typeDecl);
			activeTypeIsClass = !activeTypeIsInterface && !activeTypeIsAnnotation && !activeTypeIsEnum && !activeTypeIsRecord;
		}
	}


	void captureFieldContext(JavacNode fieldNode) {
		activeFieldNode = fieldNode;
		activeFieldName = "";
		activeFieldFlags = 0L;
		activeFieldIsStatic = false;
		activeFieldIsFinal = false;
		activeFieldIsPrivate = false;
		activeFieldIsTransient = false;
		activeFieldStartsWithDollar = false;
		if (fieldNode != null && fieldNode.get() instanceof JCVariableDecl) {
			JCVariableDecl fieldDecl = (JCVariableDecl) fieldNode.get();
			activeFieldName = fieldDecl.name.toString();
			activeFieldFlags = fieldDecl.mods.flags;
			activeFieldIsStatic = fieldDeclarationHasStaticFlag(fieldDecl);
			activeFieldIsFinal = fieldDeclarationHasFinalFlag(fieldDecl);
			activeFieldIsPrivate = fieldDeclarationHasPrivateFlag(fieldDecl);
			activeFieldIsTransient = fieldDeclarationHasTransientFlag(fieldDecl);
			activeFieldStartsWithDollar = fieldNameStartsWithDollar(activeFieldName);
		}
	}


	void captureAccessLevel(AccessLevel level) {
		activeAccessLevel = level;
		activeAccessFlags = accessLevelToJavacModifier(level);
	}


	void captureErrorContext(JavacNode errorNode) {
		activeErrorNode = errorNode;
		activeDiagnosticMessage = "";
	}


	void rememberSkipGeneration(boolean skip) {
		activeSkipGeneration = skip;
	}


	boolean consumeSkipGeneration() {
		boolean skip = activeSkipGeneration;
		return skip;
	}


	boolean activeTypeAllowsInstanceMembers() {
		if (activeTypeIsInterface) return false;
		if (activeTypeIsAnnotation) return false;
		if (activeTypeIsRecord) return false;
		return true;
	}


	boolean activeTypeAllowsGetters() {
		if (activeTypeIsInterface) return false;
		if (activeTypeIsAnnotation) return false;
		if (activeTypeIsRecord) return false;
		return activeTypeIsClass || activeTypeIsEnum;
	}


	boolean activeFieldAllowsGetter() {
		if (activeFieldStartsWithDollar) return false;
		if (activeFieldIsStatic) return false;
		return true;
	}


	boolean activeFieldAllowsSetter() {
		if (activeFieldStartsWithDollar) return false;
		if (activeFieldIsStatic) return false;
		if (activeFieldIsFinal) return false;
		return true;
	}


	boolean activeFieldAllowsConstructorParam() {
		if (activeFieldStartsWithDollar) return false;
		if (activeFieldIsStatic) return false;
		return true;
	}


	static boolean typeDeclarationHasPublicFlag(JCClassDecl typeDecl) {
		if (typeDecl == null) {
			return false;
		}
		JCModifiers modifiers = typeDecl.mods;
		if (modifiers == null) {
			return false;
		}
		long flags = modifiers.flags;
		long mask = Flags.PUBLIC;
		long masked = flags & mask;
		boolean present = masked != 0L;
		return present;
	}


