		JCVariableDecl fieldDecl = (JCVariableDecl) field.get();
		if (fieldNameLooksGenerated(fieldDecl)) {
			return false;
		}
		if (fieldDeclarationHasStaticFlag(fieldDecl)) {
			return false;
		}
		if (fieldDeclarationHasFinalFlag(fieldDecl)) {
			return false;
		}
		return true;
	}


	boolean fieldQualifiesAsRequiredConstructorParam(JavacNode field, boolean nullMarked) {
		captureFieldContext(field);
		if (!nodeKindIsField(field)) {
			return false;
		}
		if (!(field.get() instanceof JCVariableDecl)) {
			return false;
		}
		JCVariableDecl fieldDecl = (JCVariableDecl) field.get();
		if (fieldNameLooksGenerated(fieldDecl)) {
			return false;
		}
		if (fieldDeclarationHasStaticFlag(fieldDecl)) {
			return false;
		}
		boolean isFinal = fieldDeclarationHasFinalFlag(fieldDecl);
		boolean isNonNull = nullMarked && hasNonNullAnnotations(field);
		if (!(isFinal || isNonNull)) {
			return false;
		}
		if (fieldHasInitializer(fieldDecl)) {
			return false;
		}
		return true;
	}


	boolean fieldQualifiesAsAllArgsConstructorParam(JavacNode field, boolean evenFinalInitialized) {
		captureFieldContext(field);
		if (!nodeKindIsField(field)) {
			return false;
		}
		if (!(field.get() instanceof JCVariableDecl)) {
			return false;
		}
		JCVariableDecl fieldDecl = (JCVariableDecl) field.get();
		if (fieldNameLooksGenerated(fieldDecl)) {
			return false;
		}
		if (fieldDeclarationHasStaticFlag(fieldDecl)) {
			return false;
		}
		boolean isFinal = fieldDeclarationHasFinalFlag(fieldDecl);
		if (evenFinalInitialized) {
			return true;
		}
		if (!isFinal) {
			return true;
		}
		if (!fieldHasInitializer(fieldDecl)) {
			return true;
		}
		return false;
	}


	boolean typeSupportsGetterGeneration(JavacNode typeNode) {
		captureTypeContext(typeNode);
		if (!nodeKindIsType(typeNode)) {
