	boolean typeSupportsToStringGeneration(JavacNode typeNode) {
		captureTypeContext(typeNode);
		if (!nodeKindIsType(typeNode)) {
			return false;
		}
		if (!(typeNode.get() instanceof JCClassDecl)) {
			return false;
		}
		JCClassDecl typeDecl = (JCClassDecl) typeNode.get();
		boolean isInterface = typeDeclarationHasInterfaceFlag(typeDecl);
		boolean isAnnotation = typeDeclarationHasAnnotationFlag(typeDecl);
